sys_script_include.script:
var HoCOHSMClientUtils = Class.create();

HoCOHSMClientUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    //For first implementation, get inspired by "IncidentClientUtils" https://hoccdcdv.service-now.com/sys_script_include.do?sys_id=cd0c6da51bfbd1d09fde86acdd4bcb97


    // Used on catalogue items/record producer to get information about an employee/submitter from sys_user
    getSubmitterInformation: function() {
        var userID = this.getParameter("sysparm_user_id");
        var grUser = new GlideRecord('sys_user');
        var result = {};

        if (grUser.get('sys_id', userID)) {
            result = {
                "title": grUser.getDisplayValue('title'),
                "manager": grUser.getValue('manager'),
                "service_area": grUser.getDisplayValue('department.business_unit')
                // ??? Service Area
            };


        }

        return JSON.stringify(result);

    },


    type: 'HoCOHSMClientUtils'
});
